const puppeteer = require('puppeteer');

const browser = await puppeteer.launch({
  headless: 'new',
  args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
});

const page = await browser.newPage();

// Set a realistic viewport and user agent
await page.setViewport({ width: 1920, height: 1080 });
await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');

// Set Arabic language preference
await page.setExtraHTTPHeaders({
  'Accept-Language': 'ar,en-US;q=0.9,en;q=0.8'
});

try {
  // Navigate to the offers/homepage
  await page.goto('https://daralamirat.com.sa/', {
    waitUntil: 'networkidle2',
    timeout: 60000
  });

  // Wait for product elements to load
  await page.waitForTimeout(5000);

  // Try to find and click an "offers" or "عروض" link if it exists
  const offersLink = await page.$('a[href*="offer"], a[href*="عروض"], a[href*="sale"], a[href*="deal"]');
  if (offersLink) {
    await offersLink.click();
    await page.waitForNavigation({ waitUntil: 'networkidle2', timeout: 30000 }).catch(() => {});
    await page.waitForTimeout(3000);
  }

  // Extract offers data from the page
  const offers = await page.evaluate(() => {
    const results = [];

    // Common e-commerce product card selectors (covers Salla, Zid, Shopify, WooCommerce, custom)
    const productSelectors = [
      '.product-card', '.product-item', '.product-block',
      '.offer-card', '.deal-card', '.sale-item',
      '[class*="product-card"]', '[class*="product-item"]',
      '[data-product]', '.grid-product', '.product',
      '.s-product-card-entry',  // Salla
      '.woocommerce-loop-product',  // WooCommerce
      '.product-grid-item'  // Common
    ];

    let productElements = [];
    for (const selector of productSelectors) {
      const elements = document.querySelectorAll(selector);
      if (elements.length > 0) {
        productElements = elements;
        break;
      }
    }

    // If no product cards found, try broader approach
    if (productElements.length === 0) {
      // Look for any element with price-like content
      const allElements = document.querySelectorAll('[class*="product"], [class*="offer"], [class*="item"]');
      productElements = allElements;
    }

    productElements.forEach((el) => {
      // Extract title
      const titleEl = el.querySelector('h2, h3, h4, .title, .name, [class*="title"], [class*="name"], .product-title, .product-name');
      const title = titleEl ? titleEl.textContent.trim() : '';

      // Extract current price
      const priceEl = el.querySelector('.price, .sale-price, .current-price, [class*="price"]:not([class*="old"]):not([class*="was"]):not([class*="original"])');
      const price = priceEl ? priceEl.textContent.trim() : '';

      // Extract original price
      const oldPriceEl = el.querySelector('.old-price, .was-price, .original-price, del, s, [class*="old-price"], [class*="was"], [class*="original"], [class*="regular-price"]');
      const oldPrice = oldPriceEl ? oldPriceEl.textContent.trim() : '';

      // Extract image
      const imgEl = el.querySelector('img');
      const image = imgEl ? (imgEl.getAttribute('data-src') || imgEl.getAttribute('src') || '') : '';

      // Extract link
      const linkEl = el.querySelector('a[href]');
      const link = linkEl ? linkEl.getAttribute('href') : '';

      // Extract discount badge
      const badgeEl = el.querySelector('.badge, .discount, [class*="discount"], [class*="badge"], [class*="sale"], [class*="off"]');
      const discount = badgeEl ? badgeEl.textContent.trim() : '';

      if (title || price) {
        results.push({
          title,
          current_price: price,
          original_price: oldPrice,
          discount_badge: discount,
          image_url: image,
          product_link: link
        });
      }
    });

    return results;
  });

  // Also get the page title and URL for reference
  const pageTitle = await page.title();
  const pageUrl = page.url();

  await browser.close();

  // Make links absolute
  const processedOffers = offers.map(offer => ({
    ...offer,
    product_link: offer.product_link && !offer.product_link.startsWith('http')
      ? 'https://daralamirat.com.sa' + (offer.product_link.startsWith('/') ? '' : '/') + offer.product_link
      : offer.product_link,
    image_url: offer.image_url && !offer.image_url.startsWith('http')
      ? 'https://daralamirat.com.sa' + (offer.image_url.startsWith('/') ? '' : '/') + offer.image_url
      : offer.image_url
  }));

  return [
    {
      json: {
        website: 'daralamirat.com.sa',
        website_name: 'دار الأميرات - Dar Alamirat',
        page_title: pageTitle,
        page_url: pageUrl,
        scrape_date: new Date().toISOString(),
        total_offers_found: processedOffers.length,
        offers: processedOffers
      }
    }
  ];

} catch (error) {
  await browser.close();
  return [
    {
      json: {
        status: 'error',
        message: error.message,
        scraped_at: new Date().toISOString()
      }
    }
  ];
}

const data = $input.first().json;

if (data.status === 'error') {
  return [{
    json: {
      status: 'error',
      message: `Scraping failed: ${data.message}`,
      date: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    status: 'success',
    message: `Successfully scraped ${data.total_offers_found} offers from ${data.website_name}`,
    total_offers: data.total_offers_found,
    page_scraped: data.page_url,
    date: data.scrape_date,
    file_saved: `/tmp/daralamirat_offers_${new Date().toISOString().split('T')[0]}.json`
  }
}];
